pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund address(this) with enough ether to make the calls
        vm.deal(address(this), 30 ether);

        // First call: will succeed, set pastBlockTime
        uint blockTime1 = 1000;
        vm.warp(blockTime1);
        c.call{value: 10 ether}("");

        // Second call at the same block.timestamp
        vm.warp(blockTime1); // same timestamp
        bool ok;
        try c.call{value: 10 ether}("") {
